options.customCss:
/* Screenshot to Bug Reporter - submission form, dark.
   Every colour goes through the variables n8n's own form template reads
   (packages/cli/templates/form-trigger.handlebars), and the few extra rules
   below target that template's real class names: .container, .card,
   .form-header, .form-group, .form-input, .select-input, .file-input-wrapper,
   .clear-button, #submit-btn.
   The previous pass guessed with attribute-substring selectors instead, which
   is what produced the buggy form: one of them matched .inputs-wrapper and
   drew a box around every field, another matched .file-input-wrapper and made
   it dashed, and colouring anything matching "required" hit label.form-required
   - the label itself - so every required label turned red. */
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@500;600&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');

:root {
  --font-family: "IBM Plex Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-weight-normal: 400;
  --font-weight-bold: 600;
  --font-size-header: 26px;
  --font-size-paragraph: 14px;
  --font-size-label: 13px;
  --font-size-input: 15px;
  --font-size-body: 14px;
  --font-size-link: 12.5px;
  --font-size-error: 12.5px;

  --color-background: #0b0e17;
  --color-card-bg: #151b2b;
  --color-card-border: #252d42;
  --color-card-shadow: rgba(0, 0, 0, .55);
  --color-header: #eef2fb;
  --color-header-subtext: #96a1bd;
  --color-label: #cfd7ea;
  --color-link: #96a1bd;

  /* Read by "form .form-input" in the template but absent from n8n's own
     defaults - without it every field keeps a white background on a dark page. */
  --color-input-bg: #0f1422;
  --color-input-border: #2b344c;
  --color-input-text: #e8ecf7;
  --color-focus-border: #5c7cfa;

  --color-submit-btn-bg: #5c7cfa;
  --color-submit-btn-text: #ffffff;
  --color-required: #ff8f7a;
  --color-error: #ff6b6b;
  --color-clear-button-bg: #2b344c;

  --border-radius-card: 16px;
  --border-radius-input: 10px;
  --card-border-radius: 16px;
  --padding-card: 30px;
  --card-padding: 30px;
  --container-width: 520px;
  --submit-btn-height: 52px;
  --box-shadow-card: 0 24px 60px -24px var(--color-card-shadow);
}

body {
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: calc(100vw - 32px); }

/* Accent rail as a real border rather than a positioned pseudo-element, so it
   cannot drift away from the card's rounded corner. */
.card { border-left: 3px solid #5c7cfa; }

.form-header h1 {
  font-weight: 600;
  letter-spacing: -.022em;
  text-wrap: balance;
}
.form-header p { line-height: 1.6; }

/* The template ships no rules at all for these two, so spacing is whatever the
   browser defaults to. Set it deliberately. */
.form-group { margin-bottom: 20px; text-align: left; }
.form-group:last-of-type { margin-bottom: 4px; }
.form-label { letter-spacing: -.005em; }

form .form-input {
  transition: border-color .14s ease, box-shadow .14s ease, background-color .14s ease;
}
form .form-input:hover { border-color: #37425f; }
form .form-input:focus,
form textarea:focus,
form input:focus {
  box-shadow: 0 0 0 3px rgba(92, 124, 250, .22);
}
form textarea.form-input { min-height: 112px; line-height: 1.55; }
::placeholder { color: #6f7b98; opacity: 1; }

.select-input { background-color: var(--color-input-bg); }
form select { color: var(--color-input-text); }
form select option { background-color: #151b2b; color: #e8ecf7; }

/* The screenshot field carries the whole workflow, so it gets to look like a
   drop target. Scoped to the input, not to .file-input-wrapper - the wrapper
   contains the label, so bordering it boxes the label in with the control. */
.file-input-wrapper { position: relative; }
.file-input-wrapper .form-input {
  border-style: dashed;
  border-color: #35405c;
  padding: 16px 14px;
  cursor: pointer;
  color: #96a1bd;
  font-family: var(--font-family);
  font-size: 13.5px;
}
.file-input-wrapper .form-input:hover {
  border-color: #5c7cfa;
  background-color: #121a2c;
}
input[type="file"]::file-selector-button {
  margin-right: 12px;
  padding: 9px 15px;
  border: 0;
  border-radius: 8px;
  background-color: #232c44;
  color: #e8ecf7;
  font-family: var(--font-family);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color .14s ease;
}
input[type="file"]::file-selector-button:hover { background-color: #2e3a58; }

.clear-button {
  background-color: var(--color-clear-button-bg);
  color: #e8ecf7;
  border: 0;
  border-radius: 50%;
  width: 22px;
  height: 22px;
  line-height: 1;
  cursor: pointer;
}
.clear-button:hover { background-color: #3a4664; }

#submit-btn {
  letter-spacing: .01em;
  transition: filter .14s ease, transform .14s ease;
}
/* n8n fades the button to 0.7 on hover, which reads as disabled on dark. */
#submit-btn:hover { opacity: 1; filter: brightness(1.12); }
#submit-btn:active { transform: translateY(1px); }
#submit-btn:focus-visible { outline: 2px solid #5c7cfa; outline-offset: 3px; }

#submit-hint { color: var(--color-link); }

/* No n8n branding on a page a tester is asked to trust */
.n8n-link { display: none !important; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

parameters.jsCode:
// Assemble the Groq vision request.
// A Code node rather than inline expressions because the payload is a nested
// array of content parts, which is painful to express in the HTTP node.

const form = $('Bug Report Form').first();
const f = form.json;
const b64 = $input.first().json.imageBase64;

// The form names the binary property after the field label. Read the mime type
// off whatever binary key actually arrived rather than assuming PNG.
const binary = form.binary || {};
const binKey = Object.keys(binary)[0];
const mime = (binKey && binary[binKey].mimeType) || 'image/png';

const pick = (...keys) => {
  for (const k of keys) {
    if (f[k] !== undefined && String(f[k]).trim() !== '') return String(f[k]).trim();
  }
  return '';
};

const env = pick('Environment') || 'Not Provided';
const notes = pick('What were you doing');
const logs = pick('Error logs or console output');
const who = pick('Your name');

const instructions = [
  'You are a senior QA engineer writing a defect report from a screenshot.',
  '',
  'Read the image carefully and describe what is actually wrong on screen. Then',
  'produce a bug report as JSON.',
  '',
  '## THE RULE THAT MATTERS MOST',
  'A screenshot cannot show how the user got there. You must NEVER invent steps',
  'to reproduce. Do not write plausible-sounding navigation such as "Navigate to',
  'the login page" or "Enter valid credentials" unless the tester actually said so',
  'below, or it is unambiguously visible in the image.',
  'If you do not have enough to write real steps, return exactly one step reading',
  '"Not Provided - tester to complete" and set confidence to "Low".',
  'Invented steps are worse than no steps, because they look authoritative and',
  'send a developer down a path nobody took.',
  '',
  '## OTHER RULES',
  '- Transcribe error text visible in the image exactly. Never complete, correct',
  '  or paraphrase a truncated message. If it is cut off, say it is cut off.',
  '- Never claim a cause you cannot see. Describe symptoms, not diagnoses.',
  '- Anything you cannot determine is the string "Not Provided". Do not guess.',
  '- Keep every value a single line. No markdown, no line breaks inside values.',
  '',
  '## SEVERITY (technical impact, objective)',
  'S0 - Blocker  : data loss, security exposure, wrong money, total failure of a',
  '                core journey.',
  'S1 - Critical : major feature completely broken, no workaround.',
  'S2 - Major    : feature impaired or partly wrong, workaround exists.',
  'S3 - Minor    : cosmetic, layout, wording. Function still works.',
  'S4 - Trivial  : typo, alignment nitpick.',
  '',
  '## PRIORITY (business urgency)',
  'P0 - Immediate, P1 - Current Sprint, P2 - Next Sprint, P3 - Opportunistic,',
  'P4 - Backlog.',
  'Severity and priority are different. When they differ, explain it in',
  'severity_priority_explanation.',
  '',
  '## CATEGORY (pick exactly one)',
  'Functional Logic, Data and Calculation, UI/UX and Layout, Performance,',
  'Security, API and Integration, Compatibility, Configuration and Deployment,',
  'Regression, Usability and Content, Unable to Determine.',
  '',
  '## RETURN ONLY THIS JSON, no prose, no code fences',
  '{',
  '  "summary": "one line, no Bug: prefix, names the screen and the symptom",',
  '  "visible_symptom": "what is wrong on screen",',
  '  "visual_details": "layout, overlap, truncation, colour, alignment, broken image, cut-off text",',
  '  "error_text_on_screen": "verbatim, or Not Provided",',
  '  "affected_screen": "page or component, or Not Provided",',
  '  "steps_to_reproduce": ["..."],',
  '  "expected_result": "...",',
  '  "actual_result": "...",',
  '  "recommended_severity": "S0 - Blocker | S1 - Critical | S2 - Major | S3 - Minor | S4 - Trivial",',
  '  "recommended_priority": "P0 - Immediate | P1 - Current Sprint | P2 - Next Sprint | P3 - Opportunistic | P4 - Backlog",',
  '  "severity_priority_explanation": "...",',
  '  "category": "...",',
  '  "confidence": "High | Medium | Low",',
  '  "missing_information": "semicolon separated"',
  '}',
  '',
  '## WHAT THE TESTER PROVIDED',
  'Environment: ' + env,
  'What they were doing: ' + (notes || 'Not Provided'),
  'Error logs they pasted: ' + (logs || 'Not Provided'),
].join('\n');

return [{
  json: {
    _env: env,
    _notes: notes,
    _logs: logs,
    _reporter: who,
    model: 'qwen/qwen3.6-27b',
    temperature: 0.2,
    // No response_format here on purpose. Groq rejects
    // response_format: {type:'json_object'} when the message carries an image
    // (400 json_validate_failed), so the JSON contract is enforced by the
    // prompt and by defensive parsing in the next node instead.
    //
    // reasoning_effort 'none' is load-bearing, not a tweak. qwen3.6 is a
    // thinking model: left on, it spends the whole completion budget reasoning
    // and the JSON comes back truncated mid-object. Measured on one screenshot:
    // 900 completion tokens and unparseable with reasoning on, 128 tokens and
    // clean JSON with it off.
    reasoning_effort: 'none',
    // Groq counts this ceiling against the output-tokens-per-minute limit as
    // 'requested', not what is actually used, so keep it tight.
    max_completion_tokens: 800,
    messages: [
      {
        role: 'user',
        content: [
          { type: 'text', text: instructions },
          { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } },
        ],
      },
    ],
  },
}];

// Parse and harden the model's output before anything reaches Jira.
// The model returns JSON as a *string* inside choices[0].message.content, so a
// malformed response is a normal case, not an exceptional one.

const res = $input.first().json;
const ctx = $('Build Groq Request').first().json;

const content = res?.choices?.[0]?.message?.content ?? '';

let bug = null;
try {
  bug = JSON.parse(content);
} catch (e) {
  // Salvage the first {...} block, in case the model wrapped it in prose or
  // code fences despite being asked not to.
  const m = String(content).match(/\{[\s\S]*\}/);
  if (m) {
    try { bug = JSON.parse(m[0]); } catch (e2) { bug = null; }
  }
}

const parseFailed = bug === null;
if (parseFailed) bug = {};

const str = (v, fallback = 'Not Provided') => {
  if (v === undefined || v === null) return fallback;
  const s = String(v).trim();
  return s === '' ? fallback : s;
};

// Steps must survive being a string, an array, or missing entirely.
let steps = bug.steps_to_reproduce;
if (typeof steps === 'string') steps = steps.split(/\r?\n/);
if (!Array.isArray(steps)) steps = [];
steps = steps.map((s) => String(s).trim()).filter(Boolean);
if (steps.length === 0) steps = ['Not Provided - tester to complete'];

const summary = str(bug.summary, 'Bug reported from screenshot');
const confidence = parseFailed ? 'Low' : str(bug.confidence, 'Low');

const missing = [
  str(bug.missing_information, ''),
  parseFailed ? 'Model returned unparseable output; fields below are defaults' : '',
  !ctx._notes ? 'Tester did not describe what they were doing' : '',
  !ctx._logs ? 'No error logs supplied' : '',
].filter(Boolean).join('; ') || 'None';

const description = [
  'Filed automatically from a screenshot by the Screenshot to Bug Reporter agent.',
  '',
  'ENVIRONMENT',
  ctx._env,
  '',
  'WHAT IS WRONG',
  str(bug.visible_symptom),
  '',
  'VISUAL DETAIL',
  str(bug.visual_details),
  '',
  'ERROR TEXT VISIBLE ON SCREEN',
  str(bug.error_text_on_screen),
  '',
  'AFFECTED SCREEN',
  str(bug.affected_screen),
  '',
  'STEPS TO REPRODUCE',
  steps.map((s, i) => (s.startsWith('Not Provided') ? s : (i + 1) + '. ' + s)).join('\n'),
  '',
  'EXPECTED RESULT',
  str(bug.expected_result),
  '',
  'ACTUAL RESULT',
  str(bug.actual_result),
  '',
  'TRIAGE',
  'Severity: ' + str(bug.recommended_severity, 'Unable to Determine'),
  'Priority: ' + str(bug.recommended_priority, 'Unable to Determine'),
  'Category: ' + str(bug.category, 'Unable to Determine'),
  'Why they differ: ' + str(bug.severity_priority_explanation, 'Not Provided'),
  'Confidence: ' + confidence,
  '',
  'REPORTER NOTES',
  ctx._notes || 'Not Provided',
  '',
  'ERROR LOGS PASTED BY REPORTER',
  ctx._logs || 'Not Provided',
  '',
  'MISSING INFORMATION',
  missing,
  '',
  'Reported by: ' + (ctx._reporter || 'Not Provided'),
  'Severity and priority above are a suggestion from an automated first pass.',
  'Confidence "Low" means the screenshot did not carry enough to be sure.',
].join('\n');

return [{
  json: {
    summary: summary.slice(0, 250),
    description,
    confidence,
    parseFailed,
    severity: str(bug.recommended_severity, 'Unable to Determine'),
    priority: str(bug.recommended_priority, 'Unable to Determine'),
    category: str(bug.category, 'Unable to Determine'),
    environment: ctx._env,
    missingInformation: missing,
  },
}];

// Re-attach the screenshot for the Jira attachment step.
//
// Binary data does not flow through Code or HTTP nodes: "Build Groq
// Request" returns plain json, so everything downstream of it has lost
// the file. The Jira create node then outputs its own API response. By
// the attach node the binary is gone, its binaryPropertyName matches
// nothing, and the ticket is filed with no image - which is exactly the
// "Screenshot not attached" state the tester was seeing.
//
// Read it back off the trigger and hand it over under a fixed key, so
// the attach node never has to guess what the form named it.

const created = $input.first().json;
const form = $('Bug Report Form').first();
const bin = form.binary || {};
const key = Object.keys(bin)[0];

if (!key) {
  throw new Error('No binary on the form submission - nothing to attach');
}

return [{ json: created, binary: { Screenshot: bin[key] } }];

// Build the tester's confirmation page as one HTML string.
// Written as code rather than a template in the Form node so the severity /
// confidence tone logic is real logic, and the Form node needs one expression.

const bug = $('Parse Bug Report').first().json;
const issue = $('Create Jira Bug').first().json;

// The attachment step is allowed to fail without taking the run down, so a
// missing result means "not attached" rather than an error.
let attached = false;
try {
  const att = $('Attach Screenshot to Issue').first().json;
  attached = !!(att && (att.id || att.filename || (Array.isArray(att) && att.length)));
} catch (e) { attached = false; }

const key = issue.key || 'the ticket';
// Derive the browse URL from the API self link, so this works on any Jira
// site without a hardcoded host.
let browseUrl = '#';
if (issue.self) {
  const m = String(issue.self).match(/^(https?:\/\/[^/]+)/);
  if (m) browseUrl = m[1] + '/browse/' + key;
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function buildRecord(d, esc) {
  var tone = function (v, crit, warn) { return crit.test(v) ? 'crit' : warn.test(v) ? 'warn' : 'calm'; };
  var sevTone = tone(d.severity, /S0|S1/, /S2/);
  var priTone = tone(d.priority, /P0/, /P1|P2/);
  var confTone = d.confidence === 'High' ? 'good' : d.confidence === 'Medium' ? 'warn' : 'crit';
  var missing = String(d.missingInformation || '').split(';').map(function (s) { return s.trim(); }).filter(Boolean);
  var tick = '<svg viewBox="0 0 24 24"><path d="M20 6 9 17l-5-5"/></svg>';
  var bang = '<svg viewBox="0 0 24 24"><path d="M12 8v5M12 17h.01"/></svg>';

  return [
    '<main class="record" data-sev="' + sevTone + '">',
    '<div class="stripe" aria-hidden="true"></div>',
    '<div class="inner">',
      '<header>',
        '<p class="eyebrow">' + tick + 'Filed in Bug-Tracking</p>',
        '<div class="keyrow">',
          '<h1 class="key">' + esc(d.key) + '</h1>',
          d.attached
            ? '<span class="pill good">' + tick + 'Screenshot attached</span>'
            : '<span class="pill warn">' + bang + 'Screenshot not attached</span>',
        '</div>',
        '<p class="lead">' + esc(d.summary) + '</p>',
      '</header>',
      '<dl class="triage">',
        '<div><dt>Severity</dt><dd class="' + sevTone + '">' + esc(d.severity) + '</dd></div>',
        '<div><dt>Priority</dt><dd class="' + priTone + '">' + esc(d.priority) + '</dd></div>',
        '<div><dt>Category</dt><dd>' + esc(d.category) + '</dd></div>',
        '<div><dt>Confidence</dt><dd class="' + confTone + '">' + esc(d.confidence) + '</dd></div>',
      '</dl>',
      '<a class="cta" href="' + esc(d.browseUrl) + '" target="_blank" rel="noopener">',
        'Open ' + esc(d.key) + ' in Jira',
        '<svg viewBox="0 0 24 24"><path d="M7 17 17 7M9 7h8v8"/></svg>',
      '</a>',
      d.confidence !== 'High'
        ? ('<section class="callout">' +
             '<h2>Steps to reproduce are still blank</h2>' +
             '<p>A screenshot cannot show how you got there, so the steps were left empty rather than invented. Open the ticket and add them while it is fresh.</p>' +
             (missing.length
               ? '<ul>' + missing.slice(0, 5).map(function (m) { return '<li>' + esc(m) + '</li>'; }).join('') + '</ul>'
               : '') +
           '</section>')
        : '',
      '<footer class="foot">',
        '<dl class="meta">',
          '<div><dt>Environment</dt><dd>' + esc(d.environment) + '</dd></div>',
          '<div><dt>Reported</dt><dd id="filed">just now</dd></div>',
        '</dl>',
        '<a class="again" id="again" href="#">Report another bug</a>',
      '</footer>',
    '</div>',
    '</main>',
  ].join('');
}

const record = buildRecord({
  key: key,
  browseUrl: browseUrl,
  attached: attached,
  summary: bug.summary || '',
  severity: bug.severity || 'Unable to Determine',
  priority: bug.priority || 'Unable to Determine',
  category: bug.category || 'Unable to Determine',
  confidence: bug.confidence || 'Low',
  environment: bug.environment || 'Not Provided',
  missingInformation: bug.missingInformation || '',
}, esc);

// Committed dark design, so the page paints its own ground and never inherits
// a light one. The closing tag is concatenated rather than escaped - writing it
// as one literal is what shipped a stray backslash last time.
const CLOSE_SCRIPT = '<' + '/script>';

const html = [
  '<!doctype html><html lang="en"><head><meta charset="utf-8">',
  '<meta name="viewport" content="width=device-width,initial-scale=1">',
  '<meta name="color-scheme" content="dark">',
  '<title>' + esc(key) + ' filed</title>',
